        # 添加弹性空间
        nav_layout.addStretch(1)

        # 紧急停止按钮(放在导航栏底部)
        self.btn_emergency = QPushButton("紧急停止")
        self.btn_emergency.setStyleSheet("""
            QPushButton {
                background-color: #E74C3C;
                color: white;
                font-weight: bold;
                font-size: 12px;
                padding: 10px;
