        # 串口1状态
        self.port1_status_label = QLabel("串口1: ❌ 未连接")
        self.port1_status_label.setStyleSheet("""
            color: #e74c3c;
            background-color: #fdf2f2;
            padding: 6px 12px;
            font-size: 10px;
            font-weight: bold;
            border-radius: 3px;
            margin: 2px 10px;
            border: 1px solid #e74c3c;
        """)
