    QWidget, QVBoxLayout, QHBoxLayout, QGridLayout, QPushButton, QLabel, QMessageBox,QTabWidget,
    QComboBox, QLineEdit, QTextEdit, QDialog, QFormLayout, QSlider, QSpinBox, QGroupBox, QRadioButton
