        # 说明标签
        info_label = QLabel("双串口配置：串口1用于点火/灭火，串口2用于其他控制")
        info_label.setStyleSheet("font-weight: bold; color: #2980B9; padding: 10px;")
        main_layout.addWidget(info_label)

        # 使用标签页来分别配置两个串口

