        self.baud1_combo.setCurrentText("115200")
        port1_layout.addRow("波特率:", self.baud1_combo)

        # 串口1数据位
        self.data_bits1_combo = QComboBox()
        self.data_bits1_combo.addItems(["5", "6", "7", "8"])
        self.data_bits1_combo.setCurrentText("8")
